package gay.runescape;

import com.google.common.base.Strings;
import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.HashMap;
import java.util.Map;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.util.Text;

@Slf4j
@RequiredArgsConstructor
public class AccountConfig
{
    private final ConfigManager configManager;
    private final Client client;
    private final Gson gson;

    private static final String KEY_ACTIVE_GAME = "activeGameId";
    private static final String KEY_JOIN_CODE   = "joinCode";
    private static final String KEY_WRITE_KEY   = "writeKey";
    private static final String KEY_COMMANDER   = "commander";

    // gameId -> writeKey cache (stored as JSON)
    private static final String KEY_COMMANDER_KEYRING_JSON = "commanderKeyringJson";
    private static final Type MAP_TYPE = new TypeToken<Map<String, String>>(){}.getType();

    public String getActiveGameId()
    {
        String rsKey = getRsProfileKeyOrNull();
        if (rsKey != null)
        {
            return configManager.getRSProfileConfiguration(SkwidGamesConfig.GROUP, KEY_ACTIVE_GAME);
        }
        return configManager.getConfiguration(SkwidGamesConfig.GROUP, KEY_ACTIVE_GAME + "." + getLocalPlayerKey());
    }

    public void setActiveGameId(String gameId)
    {
        String rsKey = getRsProfileKeyOrNull();
        if (rsKey != null)
        {
            configManager.setRSProfileConfiguration(SkwidGamesConfig.GROUP, KEY_ACTIVE_GAME, gameId);
            return;
        }
        configManager.setConfiguration(SkwidGamesConfig.GROUP, KEY_ACTIVE_GAME + "." + getLocalPlayerKey(), gameId);
    }

    public String getJoinCode()
    {
        String rsKey = getRsProfileKeyOrNull();
        if (rsKey != null)
        {
            return configManager.getRSProfileConfiguration(SkwidGamesConfig.GROUP, KEY_JOIN_CODE);
        }
        return configManager.getConfiguration(SkwidGamesConfig.GROUP, KEY_JOIN_CODE + "." + getLocalPlayerKey());
    }

    public void setJoinCode(String joinCode)
    {
        String rsKey = getRsProfileKeyOrNull();
        if (rsKey != null)
        {
            configManager.setRSProfileConfiguration(SkwidGamesConfig.GROUP, KEY_JOIN_CODE, joinCode);
            return;
        }
        configManager.setConfiguration(SkwidGamesConfig.GROUP, KEY_JOIN_CODE + "." + getLocalPlayerKey(), joinCode);
    }

    public String getWriteKey()
    {
        String rsKey = getRsProfileKeyOrNull();
        if (rsKey != null)
        {
            String val = configManager.getRSProfileConfiguration(SkwidGamesConfig.GROUP, KEY_WRITE_KEY);
            log.debug("getWriteKey: path=RSProfile rsKey={} result={}", rsKey,
                    val == null ? "null" : (val.isBlank() ? "blank" : "present"));
            return val;
        }
        String playerKey = getLocalPlayerKey();
        String val = configManager.getConfiguration(SkwidGamesConfig.GROUP, KEY_WRITE_KEY + "." + playerKey);
        log.debug("getWriteKey: path=localPlayerKey playerKey={} result={}", playerKey,
                val == null ? "null" : (val.isBlank() ? "blank" : "present"));
        return val;
    }

    public void setWriteKey(String writeKey)
    {
        String rsKey = getRsProfileKeyOrNull();
        if (rsKey != null)
        {
            log.debug("setWriteKey: path=RSProfile rsKey={} value={}", rsKey,
                    writeKey == null ? "null" : (writeKey.isBlank() ? "blank" : "present"));
            configManager.setRSProfileConfiguration(SkwidGamesConfig.GROUP, KEY_WRITE_KEY, writeKey);
            return;
        }
        String playerKey = getLocalPlayerKey();
        log.debug("setWriteKey: path=localPlayerKey playerKey={} value={}", playerKey,
                writeKey == null ? "null" : (writeKey.isBlank() ? "blank" : "present"));
        configManager.setConfiguration(SkwidGamesConfig.GROUP, KEY_WRITE_KEY + "." + playerKey, writeKey);
    }

    public String getCommander()
    {
        return configManager.getRSProfileConfiguration(SkwidGamesConfig.GROUP, KEY_COMMANDER);
    }

    public void setCommander(String commander)
    {
        configManager.setRSProfileConfiguration(SkwidGamesConfig.GROUP, KEY_COMMANDER, commander);
    }

    public void clearGamePointers()
    {
        setActiveGameId("");
        setJoinCode("");
        setWriteKey("");
        setCommander("");
    }

    public void cacheWriteKeyForGame(final String gameId, final String writeKey)
    {
        if (Strings.isNullOrEmpty(gameId) || Strings.isNullOrEmpty(writeKey))
        {
            return;
        }
        final Map<String, String> keyring = loadCommanderKeyring();
        keyring.put(gameId, writeKey);
        saveCommanderKeyring(keyring);
    }

    public String getCachedWriteKeyForGame(final String gameId)
    {
        if (Strings.isNullOrEmpty(gameId))
        {
            return "";
        }
        final Map<String, String> keyring = loadCommanderKeyring();
        final String wk = keyring.get(gameId);
        return wk != null ? wk : "";
    }

    public void forgetWriteKeyForGame(final String gameId)
    {
        if (Strings.isNullOrEmpty(gameId))
        {
            return;
        }
        final Map<String, String> keyring = loadCommanderKeyring();
        if (keyring.remove(gameId) != null)
        {
            saveCommanderKeyring(keyring);
        }
    }

    private Map<String, String> loadCommanderKeyring()
    {
        final String raw = getCommanderKeyringJson();
        if (Strings.isNullOrEmpty(raw))
        {
            return new HashMap<>();
        }

        try
        {
            final Map<String, String> parsed = gson.fromJson(raw, MAP_TYPE);
            return parsed != null ? new HashMap<>(parsed) : new HashMap<>();
        }
        catch (Exception ignored)
        {
            // If someone edits config manually and breaks JSON, fail safe.
            return new HashMap<>();
        }
    }

    private void saveCommanderKeyring(final Map<String, String> keyring)
    {
        setCommanderKeyringJson(gson.toJson(keyring != null ? keyring : new HashMap<>()));
    }

    private String getCommanderKeyringJson()
    {
        // Stored in global (non-profile-scoped) config so write keys survive RS profile changes.
        // The keyring is keyed internally by gameId, so there is no cross-account collision risk.
        return configManager.getConfiguration(SkwidGamesConfig.GROUP, KEY_COMMANDER_KEYRING_JSON);
    }

    private void setCommanderKeyringJson(final String json)
    {
        configManager.setConfiguration(SkwidGamesConfig.GROUP, KEY_COMMANDER_KEYRING_JSON, json);
    }

    private String getLocalPlayerKey()
    {
        if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null)
        {
            return "unknown";
        }
        return Text.toJagexName(client.getLocalPlayer().getName()).toLowerCase();
    }

    private String getRsProfileKeyOrNull()
    {
        try
        {
            return configManager.getRSProfileKey();
        }
        catch (Exception e)
        {
            return null;
        }
    }
}

package gay.runescape;

import lombok.extern.slf4j.Slf4j;

import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

@Slf4j
public class EventPoller
{
    public interface Listener
    {
        void onEvent(RelayClient.EventOut e);
        void onError(Exception e);
    }

    private final RelayClient relay;
    private final Listener listener;

    private final ScheduledExecutorService exec =
            Executors.newSingleThreadScheduledExecutor(r ->
            {
                Thread t = new Thread(r, "skwid-relay-poller");
                t.setDaemon(true);
                return t;
            });

    private volatile String gameId;
    private final AtomicInteger lastSeq = new AtomicInteger(0);
    private volatile boolean running = false;

    // Handle for the scheduled task so we can cancel it
    private volatile ScheduledFuture<?> scheduled;

    public EventPoller(RelayClient relay, Listener listener)
    {
        this.relay = relay;
        this.listener = listener;
    }

    public synchronized void start(String gameId)
    {
        start(gameId, 0);
    }

    public synchronized void start(String gameId, int initialSeq)
    {
        // Restart safely
        stop();

        this.gameId = gameId;
        this.lastSeq.set(initialSeq);
        this.running = true;

        // Store the future so it can be cancelled later
        scheduled = exec.scheduleAtFixedRate(this::tick, 0, 500, TimeUnit.MILLISECONDS);
    }

    public synchronized void stop()
    {
        running = false;

        // Cancel scheduled polling task so it doesn't keep firing forever
        if (scheduled != null)
        {
            scheduled.cancel(false); // Don't interrupt if tick is currently running
            scheduled = null;
        }
    }

    public synchronized boolean isRunning()
    {
        return running;
    }

    public synchronized void shutdown()
    {
        stop();
        exec.shutdownNow();
    }

    private void tick()
    {
        if (!running) return;

        final String gid = this.gameId;
        if (gid == null || gid.isBlank()) return;

        try
        {
            int after = lastSeq.get();
            RelayClient.ReadEventsResponse resp = relay.readEvents(gid, after);

            for (RelayClient.EventOut e : resp.events)
            {
                // Advance seq monotonically
                lastSeq.set(Math.max(lastSeq.get(), e.seq));
                listener.onEvent(e);
            }
        }
        catch (Exception e)
        {
            listener.onError(e);
        }
    }
}

package gay.runescape;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.util.Text;

import java.util.List;
import java.util.Locale;
import java.util.Set;

/**
 * GameService owns "game lifecycle" + per-account pointers:
 *   - activeGameId  (everyone)
 *   - joinCode      (everyone; used to join/share)
 *   - writeKey      (commander only; used to publish events)
 *   - commander     (authoritative, from relay; used for overlays/UI)
 * The authoritative roster/state lives in the relay event log.
 * Clients maintain a local reduced view via polling (RosterReducer/EventPoller).
 */
@Slf4j
@RequiredArgsConstructor
public class GameService
{
    private final Client client;
    private final AccountConfig accountConfig;
    private final RelayGateway relay;

    public String startNewGame() throws Exception
    {
        String commander = requireLocalPlayerCanonical();

        requireRelayEnabled();

        RelayGateway.CreateGameResult created = relay.createGame(commander);

        accountConfig.setActiveGameId(created.gameId);
        accountConfig.setJoinCode(created.joinCode);
        accountConfig.setWriteKey(created.writeKey);
        accountConfig.cacheWriteKeyForGame(created.gameId, created.writeKey);
        accountConfig.setCommander(created.commander);

        return created.gameId;
    }

    public void joinGame(String joinCode) throws Exception
    {
        String code = normalizeJoinCode(joinCode);
        String me = requireLocalPlayerCanonical();

        requireRelayEnabled();

        RelayGateway.JoinResult joined = relay.joinByCode(code, me);

        accountConfig.setActiveGameId(joined.gameId);
        accountConfig.setJoinCode(code);
        accountConfig.setCommander(joined.commander);
        String cached = accountConfig.getCachedWriteKeyForGame(joined.gameId);
        log.info("joinGame: gameId={} commander={} me={} cachedWriteKey={}",
                joined.gameId, joined.commander, me,
                cached == null ? "null" : (cached.isBlank() ? "blank" : "present"));
        accountConfig.setWriteKey(cached);
    }

    public void enlist(String targetCanonical, PlayerRole playerRole) throws Exception
    {
        String gameId = requireActiveGameId();
        String writeKey = requireWriteKey();
        requireRelayEnabled();

        String player = requireCanonicalPlayer(targetCanonical);
        relay.publishEnlist(gameId, writeKey, player, playerRole);
    }

    public void eliminateAsGuard(String playerCanonical) throws Exception
    {
        requireRelayEnabled();

        String gameId = requireActiveGameId();
        String actor = requireLocalPlayerCanonical();
        relay.eliminateAsGuard(gameId, playerCanonical, actor);
    }

    public void detonateAsGuard(WorldPoint wp) throws Exception
    {
        requireRelayEnabled();

        String gameId = requireActiveGameId();
        String actor = requireLocalPlayerCanonical();
        relay.detonateAsGuard(gameId, wp.getX(), wp.getY(), wp.getPlane(), actor);
    }

    public void eliminate(String playerCanonical) throws Exception
    {
        requireRelayEnabled();

        String gameId = getActiveGameId();
        if (gameId == null || gameId.isBlank())
        {
            throw new IllegalStateException("No active game.");
        }

        String writeKey = accountConfig.getWriteKey();
        if (writeKey == null || writeKey.isBlank())
        {
            throw new IllegalStateException("Missing write key.");
        }

        relay.publishEliminated(gameId, writeKey, playerCanonical, requireLocalPlayerCanonical());
    }

    public void revive(String playerCanonical) throws Exception
    {
        requireRelayEnabled();

        String gameId = requireActiveGameId();
        String writeKey = requireWriteKey();
        relay.publishRevived(gameId, writeKey, playerCanonical);
    }

    public void reviveAsGuard(String playerCanonical) throws Exception
    {
        requireRelayEnabled();

        String gameId = requireActiveGameId();
        String actor = requireLocalPlayerCanonical();
        relay.reviveAsGuard(gameId, playerCanonical, actor);
    }

    public void removePlayer(String targetCanonical) throws Exception
    {
        String gameId = requireActiveGameId();
        String writeKey = requireWriteKey();
        requireRelayEnabled();

        String player = requireCanonicalPlayer(targetCanonical);
        relay.publishRemove(gameId, writeKey, player);
    }

    public void markTile(WorldPoint wp, String label, String tileClass, Set<String> visibleTo) throws Exception
    {
        String gameId = requireActiveGameId();
        String writeKey = requireWriteKey();
        requireRelayEnabled();
        String me = requireLocalPlayerCanonical();
        relay.publishTileMarked(gameId, writeKey, wp.getX(), wp.getY(), wp.getPlane(),
                label, me, tileClass, visibleTo);
    }

    public void unmarkTile(WorldPoint wp) throws Exception
    {
        String gameId = requireActiveGameId();
        String writeKey = requireWriteKey();
        requireRelayEnabled();
        relay.publishTileUnmarked(gameId, writeKey, wp.getX(), wp.getY(), wp.getPlane());
    }

    public List<TileMarkerReducer.TileMarkerEntry> fetchTiles(String gameId) throws Exception
    {
        return relay.fetchTiles(gameId);
    }

    public RelayClient.RosterSnapshotResponse fetchRoster(String gameId) throws Exception
    {
        return relay.fetchRoster(gameId);
    }

    public void publishStoplightState(String state) throws Exception
    {
        String gameId = requireActiveGameId();
        String writeKey = requireWriteKey();
        requireRelayEnabled();
        relay.publishStoplightState(gameId, writeKey, state);
    }

    public void leaveGameRemote() throws Exception
    {
        String gameId = getActiveGameId();
        if (gameId == null || gameId.isBlank())
        {
            return; // nothing to do
        }

        requireRelayEnabled();

        String me = requireLocalPlayerCanonical();
        relay.publishLeft(gameId, me);
    }

    public void endGame() throws Exception
    {
        String gameId = requireActiveGameId();
        String writeKey = requireWriteKey();
        requireRelayEnabled();

        relay.publishGameEnded(gameId, writeKey);
        relay.endGame(gameId, writeKey);
        accountConfig.forgetWriteKeyForGame(gameId);
        clearActiveGameLocally();
    }

    // ----------------------------
    // Per-account state access
    // ----------------------------

    public String getActiveGameId() { return accountConfig.getActiveGameId(); }
    public String getJoinCode()     { return accountConfig.getJoinCode(); }
    public String getWriteKey()     { return accountConfig.getWriteKey(); }
    public String getCommander()    { return accountConfig.getCommander(); }

    /**
     * Proactively restores the write key from the keyring if the active slot is blank.
     * Call this during resume so isLocalCommander() returns the correct value before
     * any user action triggers requireWriteKey().
     */
    public void tryRestoreWriteKey()
    {
        String gameId = accountConfig.getActiveGameId();
        if (gameId == null || gameId.isBlank()) return;
        String writeKey = accountConfig.getWriteKey();
        if (writeKey != null && !writeKey.isBlank()) return;
        String cached = accountConfig.getCachedWriteKeyForGame(gameId);
        if (cached != null && !cached.isBlank())
        {
            log.debug("tryRestoreWriteKey: restored from keyring for gameId={}", gameId);
            accountConfig.setWriteKey(cached);
        }
    }

    public void clearActiveGameLocally()
    {
        accountConfig.clearGamePointers(); // should clear gameId/joinCode/writeKey/commander
    }

    // ----------------------------
    // Validation + normalization
    // ----------------------------

    private void requireRelayEnabled()
    {
        if (!relay.isEnabled())
        {
            throw new IllegalStateException("Relay is not configured/enabled.");
        }
    }

    private String requireActiveGameId()
    {
        String gameId = accountConfig.getActiveGameId();
        if (gameId == null || gameId.isBlank())
        {
            throw new IllegalStateException("No active game. Start or join a game first.");
        }
        return gameId;
    }

    private String requireWriteKey()
    {
        String gameId = accountConfig.getActiveGameId();
        String writeKey = accountConfig.getWriteKey();
        String cachedKey = gameId != null ? accountConfig.getCachedWriteKeyForGame(gameId) : null;
        log.debug("requireWriteKey: gameId={} writeKey={} cachedKey={}",
                gameId,
                writeKey == null ? "null" : (writeKey.isBlank() ? "blank" : "present"),
                cachedKey == null ? "null" : (cachedKey.isBlank() ? "blank" : "present"));

        // Active slot can end up blank (e.g. after clearGamePointers or a missed join restore).
        // Fall back to the keyring if we have a cached key for this game.
        if ((writeKey == null || writeKey.isBlank()) && cachedKey != null && !cachedKey.isBlank())
        {
            log.debug("requireWriteKey: active slot blank, restoring from keyring for gameId={}", gameId);
            accountConfig.setWriteKey(cachedKey);
            writeKey = cachedKey;
        }

        if (writeKey == null || writeKey.isBlank())
        {
            throw new IllegalStateException("Only the Commander can perform this action in the current game.");
        }
        return writeKey;
    }

    private String requireLocalPlayerCanonical()
    {
        if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null)
        {
            throw new IllegalStateException("Not logged in yet (no local player).");
        }
        return Text.toJagexName(client.getLocalPlayer().getName());
    }

    private static String normalizeJoinCode(String joinCode)
    {
        if (joinCode == null) throw new IllegalArgumentException("joinCode is required.");
        String code = joinCode.trim().toUpperCase(Locale.ROOT);
        if (code.isBlank()) throw new IllegalArgumentException("joinCode is required.");
        return code;
    }

    /**
     * Defensive: ensures we only ever send canonical RSNs to the relay.
     * (Prevents "(level 126)" and weird whitespace from leaking into events.)
     */
    private static String requireCanonicalPlayer(String player)
    {
        if (player == null) throw new IllegalArgumentException("player is required.");
        String canon = Text.toJagexName(player);
        if (canon == null || canon.isBlank())
        {
            throw new IllegalArgumentException("player is required.");
        }
        return canon;
    }

    // In GameService
    public boolean isLocalCommander()
    {
        String writeKey = accountConfig.getWriteKey();
        return isLocalPlayerCommanderByName() &&
                writeKey != null && !writeKey.isBlank();
    }

    public boolean isLocalPlayerCommanderByName()
    {
        if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null) return false;
        String me = Text.toJagexName(client.getLocalPlayer().getName());
        String commander = accountConfig.getCommander();
        if (commander == null || commander.isBlank()) return false;
        return me.equals(Text.toJagexName(commander));
    }

    // ----------------------------
    // Relay abstraction
    // ----------------------------

    public interface RelayGateway
    {
        boolean isEnabled();

        final class CreateGameResult
        {
            public final String gameId;
            public final String joinCode;
            public final String writeKey;
            public final String commander;

            public CreateGameResult(String gameId, String joinCode, String writeKey, String commander)
            {
                this.gameId = gameId;
                this.joinCode = joinCode;
                this.writeKey = writeKey;
                this.commander = commander;
            }
        }

        final class JoinResult
        {
            public final String gameId;
            public final String commander;

            public JoinResult(String gameId, String commander)
            {
                this.gameId = gameId;
                this.commander = commander;
            }
        }

        CreateGameResult createGame(String commanderCanonical) throws Exception;

        JoinResult joinByCode(String joinCode, String playerCanonical) throws Exception;

        void publishEnlist(String gameId, String writeKey, String playerCanonical, PlayerRole playerRole) throws Exception;

        void publishEliminated(String gameId, String writeKey, String playerCanonical, String actor) throws Exception;

        void publishRemove(String gameId, String writeKey, String playerCanonical) throws Exception;

        void publishLeft(String gameId, String playerCanonical) throws Exception;

        void eliminateAsGuard(String gameId, String playerCanonical, String actorCanonical) throws Exception;

        void detonateAsGuard(String gameId, int x, int y, int plane, String actorCanonical) throws Exception;

        void publishRevived(String gameId, String writeKey, String playerCanonical) throws Exception;

        void reviveAsGuard(String gameId, String playerCanonical, String actorCanonical) throws Exception;

        void publishGameEnded(String gameId, String writeKey) throws Exception;

        void endGame(String gameId, String writeKey) throws Exception;

        void publishTileMarked(String gameId, String writeKey, int x, int y, int plane,
                               String label, String markedBy,
                               String tileClass, Set<String> visibleTo) throws Exception;

        void publishTileUnmarked(String gameId, String writeKey, int x, int y, int plane) throws Exception;

        List<TileMarkerReducer.TileMarkerEntry> fetchTiles(String gameId) throws Exception;

        RelayClient.RosterSnapshotResponse fetchRoster(String gameId) throws Exception;

        void publishStoplightState(String gameId, String writeKey, String state) throws Exception;
    }
}

package gay.runescape;

public enum PlayerRole
{
    COMMANDER,
    GUARD,
    CONTESTANT,
    REMOVED
}

package gay.runescape;

public enum PlayerStatus {
    ALIVE,
    ELIMINATED
}

package gay.runescape;

import com.google.gson.Gson;
import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.*;

import java.io.IOException;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.TimeUnit;

@Slf4j
public class RelayClient implements GameService.RelayGateway
{
    private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");

    private final OkHttpClient http;
    private final Gson gson;

    private final String baseUrl;

    public RelayClient(String baseUrl, OkHttpClient httpClient, Gson gson)
    {
        this.baseUrl = normalizeBaseUrl(baseUrl);
        this.http = httpClient.newBuilder()
                .connectTimeout(10, TimeUnit.SECONDS)
                .readTimeout(15, TimeUnit.SECONDS)
                .writeTimeout(15, TimeUnit.SECONDS)
                .build();
        this.gson = gson;
    }

    @Override
    public boolean isEnabled()
    {
        return baseUrl != null && !baseUrl.isBlank();
    }

    @Override
    public CreateGameResult createGame(String commanderCanonical) throws Exception
    {
        JsonObject body = new JsonObject();
        body.addProperty("commander", commanderCanonical);

        String url = baseUrl + "/v1/games";

        Request req = new Request.Builder()
                .url(url)
                .post(RequestBody.create(JSON, gson.toJson(body)))
                .build();

        try (Response resp = http.newCall(req).execute())
        {
            String respBody = resp.body() != null ? resp.body().string() : "";
            if (!resp.isSuccessful())
            {
                throw new IOException("Create game failed (" + resp.code() + "): " + respBody);
            }

            CreateGameResponse parsed = gson.fromJson(respBody, CreateGameResponse.class);
            if (parsed == null || isBlank(parsed.gameId) || isBlank(parsed.joinCode) || isBlank(parsed.writeKey) || isBlank(parsed.commander))
            {
                throw new IOException("Create game returned invalid response: " + respBody);
            }

            return new CreateGameResult(parsed.gameId, parsed.joinCode, parsed.writeKey, parsed.commander);
        }
    }

    @Override
    public JoinResult joinByCode(String joinCode, String playerCanonical) throws Exception
    {
        JsonObject body = new JsonObject();
        body.addProperty("player", playerCanonical);

        String url = baseUrl + "/v1/join/" + joinCode;

        Request req = new Request.Builder()
                .url(url)
                .post(RequestBody.create(JSON, gson.toJson(body)))
                .build();

        try (Response resp = http.newCall(req).execute())
        {
            String respBody = resp.body() != null ? resp.body().string() : "";
            if (!resp.isSuccessful())
            {
                throw new IOException("Join failed (" + resp.code() + "): " + respBody);
            }

            JoinInfoResponse parsed = gson.fromJson(respBody, JoinInfoResponse.class);
            if (parsed == null || isBlank(parsed.gameId) || isBlank(parsed.commander))
            {
                throw new IOException("Join returned invalid response: " + respBody);
            }

            return new JoinResult(parsed.gameId, parsed.commander);
        }
    }

    @Override
    public void publishEnlist(String gameId, String writeKey, String playerCanonical, PlayerRole playerRole) throws Exception
    {
        JsonObject payload = new JsonObject();
