            if (!resp.isSuccessful())
            {
                throw new IOException("Fetch roster failed (" + resp.code() + "): " + respBody);
            }

            RosterSnapshotResponse parsed = gson.fromJson(respBody, RosterSnapshotResponse.class);
            if (parsed == null)
            {
                throw new IOException("Fetch roster returned invalid response: " + respBody);
            }
            if (parsed.players == null)
            {
                parsed.players = Collections.emptyList();
            }
            return parsed;
        }
    }

    private void publishEvent(String gameId, String writeKey, String type, JsonObject payload) throws Exception
    {
        String url = baseUrl + "/v1/games/" + gameId + "/events";

        JsonObject body = new JsonObject();
        body.addProperty("eventId", makeEventId(type, playerSafe(payload)));
        body.addProperty("ts", java.time.Instant.now().toString());
        body.addProperty("type", type);
        body.add("payload", payload);

        Request req = new Request.Builder()
                .url(url)
                .post(RequestBody.create(JSON, gson.toJson(body)))
                .header("Authorization", "Bearer " + writeKey)
                .build();

        try (Response resp = http.newCall(req).execute())
        {
            String respBody = resp.body() != null ? resp.body().string() : "";
            if (!resp.isSuccessful())
            {
                throw new IOException("Publish " + type + " failed (" + resp.code() + "): " + respBody);
            }
        }
    }

    public ReadEventsResponse readEvents(String gameId, int afterSeq) throws Exception
    {
        String url = baseUrl + "/v1/games/" + gameId + "/events?afterSeq=" + afterSeq;

        Request req = new Request.Builder()
                .url(url)
                .get()
                .build();

        try (Response resp = http.newCall(req).execute())
        {
            String respBody = resp.body() != null ? resp.body().string() : "";
            if (!resp.isSuccessful())
            {
                throw new IOException("Read events failed (" + resp.code() + "): " + respBody);
            }

            ReadEventsResponse parsed = gson.fromJson(respBody, ReadEventsResponse.class);
            if (parsed == null)
            {
                throw new IOException("Read events returned invalid response: " + respBody);
            }
            if (parsed.events == null)
            {
                parsed.events = java.util.Collections.emptyList();
            }
            return parsed;
        }
    }

    // -------- response models (match server JSON keys) --------

    private static class CreateGameResponse
    {
        String gameId;
        String joinCode;
        String writeKey;
        String createdAt;
        String commander;
    }

    private static class JoinInfoResponse
    {
        String gameId;
        String commander;
        String status;
        String createdAt;
        String endedAt;
    }

    public static class ReadEventsResponse
    {
        String gameId;
        int latestSeq;
        java.util.List<EventOut> events;
    }

    public static class EventOut
    {
        int seq;
        String eventId;
        String ts;
        String type;
        com.google.gson.JsonObject payload;
        String actor;
    }

    private static class FetchTilesResponse
    {
        String gameId;
        java.util.List<TileOut> tiles;
    }

    private static class TileOut
    {
        int x;
        int y;
        int plane;
        String label;
        String color;
        String markedBy;
        String tileClass;
        List<String> visibleTo;
    }

    public static class RosterSnapshotResponse
    {
        public String gameId;
        public int latestSeq;
        public java.util.List<RosterPlayerOut> players;
    }

    public static class RosterPlayerOut
    {
        public String rsn;
        public String role;
        public Integer number;
        public String status;
        public boolean joined;
    }

    // -------- small helpers --------

    private static String normalizeBaseUrl(String s)
    {
        if (s == null) return "";
        String x = s.trim();
        while (x.endsWith("/")) x = x.substring(0, x.length() - 1);
        return x;
    }

    private static boolean isBlank(String s)
    {
        return s == null || s.trim().isEmpty();
    }

    private static String makeEventId(String type, String suffix)
    {
        // deterministic-ish uniqueness: type + time + a little random
        String t = java.time.Instant.now().toString().replace(":", "").replace("-", "");
        int r = (int) (Math.random() * 0xFFFF);
        return "e_" + t + "_" + type.toUpperCase(Locale.ROOT) + "_" + suffix + "_" + String.format("%04X", r);
    }

    private static String playerSafe(JsonObject payload)
    {
        try
        {
            if (payload != null && payload.has("player") && !payload.get("player").isJsonNull())
            {
                String p = payload.get("player").getAsString();
                if (p == null) return "na";
                return p.replaceAll("[^A-Za-z0-9]+", "");
            }
        }
        catch (Exception ignored) { }
        return "na";
    }
}

package gay.runescape;

import javax.inject.Inject;
import java.awt.*;
import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;

public class RoleOverlay extends Overlay
{
    private final Client client;
    private final SkwidGamesConfig config;
    private final GameService gameService;
    private final RosterReducer roster;

    private static final float FONT_SIZE_PT = 16f;
    private final Font font = FontManager.getRunescapeBoldFont().deriveFont(FONT_SIZE_PT);

    private final BufferedImage commanderIcon;
    private final BufferedImage guardIcon;

    static final Color CONTESTANT_ALIVE_COLOR       = new Color(25, 177, 86);
    private static final Color CONTESTANT_ELIMINATED_COLOR = new Color(214, 9, 65);
    private static final Color COMMANDER_COLOR      = new Color(246, 101, 244);
    static final Color GUARD_COLOR                  = new Color(246, 101, 244);

    private static final Color JOINED_COLOR = new Color(255, 222, 0);
    private static final Color REMOVED_COLOR    = new Color(24, 66, 5, 255);

    @Inject
    public RoleOverlay(Client client, SkwidGamesConfig config, GameService gameService, RosterReducer roster)
    {
        this.client = client;
        this.config = config;
        this.gameService = gameService;
        this.roster = roster;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);

        commanderIcon = ImageUtil.resizeImage(
                ImageUtil.loadImageResource(RoleOverlay.class, "commander_icon.png"), 16, 16);
        guardIcon     = ImageUtil.resizeImage(
                ImageUtil.loadImageResource(RoleOverlay.class, "guard_icon.png"), 16, 16);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        if (!config.showOverlay()) return null;

        String gameId = gameService.getActiveGameId();
        if (gameId == null || gameId.isBlank()) return null;

        g.setFont(font);

        // Commander (set from relay on start/join)
        final String commanderRaw = gameService.getCommander();
        final String commanderCanon = (commanderRaw == null || commanderRaw.isBlank())
                ? null
                : Text.toJagexName(commanderRaw);

        // Local player canonical name
        final String localCanon = client.getLocalPlayer() != null && client.getLocalPlayer().getName() != null
                ? Text.toJagexName(client.getLocalPlayer().getName())
                : null;

        // We only consider ourselves commander if we have a writeKey
        final boolean iAmCommander = gameService.isLocalCommander();

        for (Player p : client.getPlayers())
        {
            if (p == null || p.getName() == null) continue;

            String rsn = Text.toJagexName(p.getName());
            if (rsn == null || rsn.isBlank()) continue;

            // Roster-derived most-recent enlist role (GUARD/CONTESTANT/REMOVED)
            PlayerRole role = roster.getRole(rsn);

            // If removed, don't show anything (even if they were commander)
            if (role == PlayerRole.REMOVED) continue;

            // Commander identifier
            final boolean isCommander = rsn.equals(commanderCanon);

            // Commander and Guard use PNG icons
            if (isCommander || role == PlayerRole.GUARD)
            {
                BufferedImage icon = isCommander ? commanderIcon : guardIcon;
                if (icon != null)
                {
                    int yOffset = p.getLogicalHeight() + icon.getHeight();
                    net.runelite.api.Point loc = p.getCanvasImageLocation(icon, yOffset);
                    if (loc != null)
                    {
                        g.drawImage(icon, loc.getX(), loc.getY(), null);
                    }
                }
                continue;
            }

            final String label;
            final Color color;

            if (role == PlayerRole.CONTESTANT)
            {
                Integer n = roster.getNumber(rsn);

                if (roster.getStatus(rsn) == PlayerStatus.ELIMINATED)
                {
                    color = CONTESTANT_ELIMINATED_COLOR;
                }
                else
                {
                    color = CONTESTANT_ALIVE_COLOR;
                }
                // If enlisted as contestant but number hasn't arrived yet, show "?"
                // This will also format the number as 0-padded 3-digit integer
                label = (n != null && n > 0) ? String.format("%03d", n) : "?";
            }
            else
            {
                // Joined but not enlisted yet
                if (!roster.hasJoined(rsn))
                {
                    continue; // hasn't joined (or we don't know about them)
                }
                label = "???";
                color = JOINED_COLOR;
            }

            int yOffset = p.getLogicalHeight() + (int) (FONT_SIZE_PT * 0.6f);
            net.runelite.api.Point loc = p.getCanvasTextLocation(g, label, yOffset);
            if (loc != null)
            {
                OverlayUtil.renderTextLocation(g, loc, label, color);
            }
        }

        return null;
    }
}

package gay.runescape;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import net.runelite.client.util.Text;

public class RosterReducer
{
    private final ConcurrentHashMap<String, PlayerRole> roleByPlayer = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, Integer> numberByPlayer = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, PlayerStatus> statusByPlayer = new ConcurrentHashMap<>();
    private final ConcurrentHashMap<String, String> displayNameByPlayer = new ConcurrentHashMap<>();
    private final Set<String> joinedPlayers = ConcurrentHashMap.newKeySet();

    public static final class SnapshotPlayer
    {
        public final String rsn;
        public final String role;
        public final Integer number;
        public final String status;
        public final boolean joined;

        public SnapshotPlayer(String rsn, String role, Integer number, String status, boolean joined)
        {
            this.rsn    = rsn;
            this.role   = role;
            this.number = number;
            this.status = status;
            this.joined = joined;
        }
    }

    public static final class RosterEntry
    {
        public final String rsn;           // canonical RSN (lowercase or normalized)
        public final Integer number;       // may be null
        public final PlayerRole role;      // CONTESTANT / GUARD / REMOVED / null
        public final PlayerStatus status;  // ALIVE / ELIMINATED / null
        public final boolean joined;       // whether we've seen PLAYER_JOINED

        public RosterEntry(String rsn,
                           Integer number,
                           PlayerRole role,
                           PlayerStatus status,
                           boolean joined)
        {
            this.rsn = rsn;
            this.number = number;
            this.role = role;
            this.status = status;
            this.joined = joined;
        }
    }

    public PlayerRole getRole(String canonicalRsn)
    {
        if (canonicalRsn == null) return null;
        return roleByPlayer.get(canonicalRsn.toLowerCase());
    }

    public Integer getNumber(String canonicalRsn)
    {
        if (canonicalRsn == null) return null;
        return numberByPlayer.get(canonicalRsn.toLowerCase());
    }

    public PlayerStatus getStatus(String canonicalRsn)
    {
        if (canonicalRsn == null) return null;
        return statusByPlayer.get(canonicalRsn.toLowerCase());
    }

    /** Reverse lookup: given a contestant number, return the canonical RSN, or null if not found. */
    public String getRsnByNumber(int number)
    {
        for (Map.Entry<String, Integer> entry : numberByPlayer.entrySet())
        {
            if (entry.getValue() == number)
            {
                return entry.getKey();
            }
        }
        return null;
    }

    public Map<String, PlayerRole> rolesSnapshot()
    {
        return Collections.unmodifiableMap(roleByPlayer);
    }

    public void reset()
    {
        roleByPlayer.clear();
        numberByPlayer.clear();
        statusByPlayer.clear();
        displayNameByPlayer.clear();
        joinedPlayers.clear();
    }

    public void loadSnapshot(List<SnapshotPlayer> players)
    {
        reset();
        if (players == null) return;

        for (SnapshotPlayer p : players)
        {
            if (p == null || p.rsn == null) continue;

            final String key = canonicalKey(p.rsn);
            if (key == null) continue;

            displayNameByPlayer.put(key, displayName(p.rsn));

            if (p.joined) joinedPlayers.add(key);

            if (p.role != null)
            {
                try
                {
                    PlayerRole role = PlayerRole.valueOf(p.role.trim().toUpperCase(Locale.ROOT));
                    roleByPlayer.put(key, role);

                    if (isContestant(role) && p.number != null && p.number > 0)
                    {
                        numberByPlayer.put(key, p.number);
                    }
                }
                catch (IllegalArgumentException ignored) { }
            }

            if (p.status != null)
            {
                try
                {
                    statusByPlayer.put(key, PlayerStatus.valueOf(p.status.trim().toUpperCase(Locale.ROOT)));
                }
                catch (IllegalArgumentException ignored) { }
            }
        }
    }

    public void apply(RelayClient.EventOut e)
    {
        if (e == null || e.type == null) return;

        final String type = e.type.toUpperCase(Locale.ROOT);

        if ("PLAYER_JOINED".equals(type))
        {
            final String playerRaw = safeStr(e.payload, "player");
            if (playerRaw == null) return;

            final String playerKey = canonicalKey(playerRaw);
            if (playerKey == null) return;

            displayNameByPlayer.putIfAbsent(playerKey, displayName(playerRaw));

            // Presence only. No number assignment here.
            // Use putIfAbsent so an existing ELIMINATED status is not overwritten.
            statusByPlayer.putIfAbsent(playerKey, PlayerStatus.ALIVE);

            // Keep track of players who have joined
            joinedPlayers.add(playerKey);

            return;
        }

        if ("ENLIST".equals(type))
        {
            final String playerRaw = safeStr(e.payload, "player");
            final String roleRaw   = safeStr(e.payload, "role");
            if (playerRaw == null || roleRaw == null) return;

            final String playerKey = canonicalKey(playerRaw);
            if (playerKey == null) return;

            displayNameByPlayer.putIfAbsent(playerKey, displayName(playerRaw));

            final PlayerRole role;
            try
            {
                role = PlayerRole.valueOf(roleRaw.trim().toUpperCase(Locale.ROOT));
            }
            catch (Exception ignored)
            {
                return;
            }

            roleByPlayer.put(playerKey, role);

            // Only contestants get (sticky) numbers
            if (isContestant(role))
            {
                final Integer number = safeInt(e.payload, "number"); // relay assigns
                if (number != null && number > 0)
                {
                    numberByPlayer.putIfAbsent(playerKey, number); // sticky
                }

                statusByPlayer.put(playerKey, PlayerStatus.ALIVE);
            }
            else
            {
                // Guards/Commander never have a number; defensively clear stale numbers
                numberByPlayer.remove(playerKey);
            }
            return;
        }

        if ("ELIMINATED".equals(type))
        {
            final String playerRaw = safeStr(e.payload, "player");
            if (playerRaw == null) return;

            final String playerKey = canonicalKey(playerRaw);
            if (playerKey == null) return;

            statusByPlayer.put(playerKey, PlayerStatus.ELIMINATED);
            return;
        }

        if ("REVIVED".equals(type))
        {
            final String playerRaw = safeStr(e.payload, "player");
            if (playerRaw == null) return;

            final String playerKey = canonicalKey(playerRaw);
            if (playerKey == null) return;

            statusByPlayer.put(playerKey, PlayerStatus.ALIVE);
            return;
        }

        if ("REMOVE".equals(type))
        {
            final String playerRaw = safeStr(e.payload, "player");
            if (playerRaw == null) return;

            final String playerKey = canonicalKey(playerRaw);
            if (playerKey == null) return;

            roleByPlayer.put(playerKey, PlayerRole.REMOVED);

            // Sticky numbering rule:
            // Do NOT clear number/status so a contestant can re-join and keep their number.
            return;
        }

        if ("PLAYER_LEFT".equals(type))
        {
            final String playerRaw = safeStr(e.payload, "player");
            if (playerRaw == null) return;

            final String playerKey = canonicalKey(playerRaw);
            if (playerKey == null) return;

            // Fully forget this player from the current game
            roleByPlayer.remove(playerKey);
            numberByPlayer.remove(playerKey);
            statusByPlayer.remove(playerKey);
            joinedPlayers.remove(playerKey);

            return;
        }
    }

    public List<RosterEntry> snapshot()
    {
        Map<String, RosterEntry> tmp = new HashMap<>();

        // Start with joined players
        for (String playerKey : joinedPlayers)
        {
            PlayerRole role = roleByPlayer.get(playerKey);
            PlayerStatus status = statusByPlayer.get(playerKey);
            Integer number = numberByPlayer.get(playerKey);
            String display = displayNameByPlayer.getOrDefault(playerKey, playerKey);

            tmp.put(playerKey, new RosterEntry(
                    display,
                    number,
                    role,
                    status,
                    true
            ));
        }

        // Also include players we know about via role/status/number but who aren't in joinedPlayers
        for (String playerKey : roleByPlayer.keySet())
        {
            if (tmp.containsKey(playerKey)) continue;

            PlayerRole role = roleByPlayer.get(playerKey);
            PlayerStatus status = statusByPlayer.get(playerKey);
            Integer number = numberByPlayer.get(playerKey);
            String display = displayNameByPlayer.getOrDefault(playerKey, playerKey);

            tmp.put(playerKey, new RosterEntry(
                    display,
                    number,
                    role,
                    status,
                    false
            ));
        }

        // Removed players are hidden from the roster (internal state is kept for sticky number re-assignment)
        tmp.values().removeIf(e -> e.role == PlayerRole.REMOVED);

        // Convert to list and sort
        List<RosterEntry> out = new ArrayList<>(tmp.values());

        out.sort((a, b) ->
        {
            boolean aContestant = a.role == PlayerRole.CONTESTANT;
            boolean bContestant = b.role == PlayerRole.CONTESTANT;

            // Contestants first
            if (aContestant && !bContestant) return -1;
            if (!aContestant && bContestant) return 1;

            // Among contestants, sort by number if present
            if (aContestant && bContestant)
            {
                int an = (a.number != null) ? a.number : Integer.MAX_VALUE;
                int bn = (b.number != null) ? b.number : Integer.MAX_VALUE;
                int cmp = Integer.compare(an, bn);
                if (cmp != 0) return cmp;
            }

            // Fallback: alphabetical by rsn
            return a.rsn.compareTo(b.rsn);
        });

        return out;
    }

    private static String canonicalKey(String playerRaw)
    {
        if (playerRaw == null) return null;

        String s = Text.removeTags(playerRaw);
        s = s.replaceFirst("\\s*\\(level\\s*-?\\s*\\d+\\)\\s*$", "");

        String canon = Text.toJagexName(s);
        if (canon == null || canon.isBlank()) return null;

        return canon.toLowerCase(Locale.ROOT);
    }

    /** Returns the properly-cased display name for a raw player string from an event payload. */
    private static String displayName(String playerRaw)
    {
        if (playerRaw == null) return playerRaw;

        String s = Text.removeTags(playerRaw);
        s = s.replaceFirst("\\s*\\(level\\s*-?\\s*\\d+\\)\\s*$", "");

        String canon = Text.toJagexName(s);
        return (canon != null && !canon.isBlank()) ? canon : s.trim();
    }

    private static boolean isContestant(PlayerRole role)
    {
        return role == PlayerRole.CONTESTANT;
    }


    public boolean hasJoined(String canonicalRsn)
    {
        if (canonicalRsn == null) return false;
        return joinedPlayers.contains(canonicalRsn.toLowerCase());
    }


    private static String safeStr(com.google.gson.JsonObject o, String key)
    {
        return (o != null && o.has(key) && !o.get(key).isJsonNull())
                ? o.get(key).getAsString()
                : null;
    }

    private static Integer safeInt(com.google.gson.JsonObject o, String key)
    {
        try
        {
            return (o != null && o.has(key) && !o.get(key).isJsonNull())
                    ? o.get(key).getAsInt()
                    : null;
        }
        catch (Exception ignored)
        {
            return null;
        }
    }
}

package gay.runescape;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.util.Text;
import net.runelite.client.util.ImageUtil;

import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.Collection;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class SharedTileOverlay extends Overlay
{
    // Default border colors used when entry.color is absent or unparseable
    private static final Color COLOR_STANDARD            = new Color(255, 255,   0, 200); // yellow
    private static final Color COLOR_LANDMINE            = new Color(  0,   0,   0, 200); // charcoal
    private static final Color COLOR_LANDMINE_DETONATED  = new Color(255, 106,   0, 200); // orange-red
    private static final Color COLOR_STOPLIGHT_RED       = new Color(255,   0,   0, 200); // red
    private static final Color COLOR_STOPLIGHT_GREEN     = new Color(  0, 255,   0, 200); // green

    private static final long  DETONATION_ANIM_DURATION_MS = 1500;

    /**
     * Keyed by WorldPoint string. Populated only when a tile transitions INTO LANDMINE_DETONATED.
     * Removed when the tile leaves the snapshot.
     */
    private final Map<String, Long> detonationTimes = new HashMap<>();
    /** Last-seen tileClass per tile, used to detect transitions. */
    private final Map<String, String> previousTileClass = new HashMap<>();

    private final Client client;
    private final SkwidGamesConfig config;
    private final GameService gameService;
    private final TileMarkerReducer tileMarkers;
    private final RosterReducer roster;

    public SharedTileOverlay(Client client, SkwidGamesConfig config,
                             GameService gameService, TileMarkerReducer tileMarkers,
                             RosterReducer roster)
    {
        this.client      = client;
        this.config      = config;
        this.gameService = gameService;
        this.tileMarkers = tileMarkers;
        this.roster      = roster;

        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        if (!config.showTileOverlay()) return null;

        String gameId = gameService.getActiveGameId();
        if (gameId == null || gameId.isBlank()) return null;

        List<TileMarkerReducer.TileMarkerEntry> entries = tileMarkers.snapshot();
        if (entries.isEmpty()) return null;

        String localRole = resolveLocalRole();

        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        // Update transition tracking: detect tiles that just became LANDMINE_DETONATED.
        java.util.Set<String> currentKeys = new java.util.HashSet<>();
        for (TileMarkerReducer.TileMarkerEntry e : entries)
        {
            String key = e.point.toString();
            currentKeys.add(key);
            String prev = previousTileClass.get(key);
            if ("LANDMINE_DETONATED".equals(e.tileClass) && "LANDMINE".equals(prev))
                detonationTimes.put(key, System.currentTimeMillis());
            previousTileClass.put(key, e.tileClass);
        }
        // Clean up state for tiles no longer in the snapshot.
        previousTileClass.keySet().retainAll(currentKeys);
        detonationTimes.keySet().retainAll(currentKeys);

        for (TileMarkerReducer.TileMarkerEntry entry : entries)
        {
            if (!isVisibleToRole(entry, localRole)) continue;
            renderMarker(g, entry);
        }

        return null;
    }

    private void renderMarker(Graphics2D g, TileMarkerReducer.TileMarkerEntry entry)
    {
        WorldPoint wp = entry.point;

        Collection<WorldPoint> localPoints = WorldPoint.toLocalInstance(client.getTopLevelWorldView(), wp);
        for (WorldPoint local : localPoints)
        {
            LocalPoint lp = LocalPoint.fromWorld(client.getTopLevelWorldView(), local);
            if (lp == null) continue;

            Polygon poly = Perspective.getCanvasTilePoly(client, lp);
            if (poly == null) continue;

            Color base   = resolveColor(entry);
            Color fill   = new Color(base.getRed(), base.getGreen(), base.getBlue(), 60);
            Color border = new Color(base.getRed(), base.getGreen(), base.getBlue(), 200);

            g.setColor(fill);
            g.fillPolygon(poly);

            g.setColor(border);
            g.setStroke(new BasicStroke(1f));
            g.drawPolygon(poly);

            if (entry.label != null && !entry.label.isBlank())
            {
                int cx = (int) poly.getBounds().getCenterX();
                int cy = (int) poly.getBounds().getCenterY();
                OverlayUtil.renderTextLocation(g, new net.runelite.api.Point(cx, cy), entry.label, border);
            }
        }
    }

    // -------------------------------------------------------------------------
    // Visibility helpers
    // -------------------------------------------------------------------------

    private String resolveLocalRole()
    {
        if (gameService.isLocalCommander()) return "COMMANDER";
        if (client.getLocalPlayer() == null || client.getLocalPlayer().getName() == null) return null;
        String rsn = Text.toJagexName(client.getLocalPlayer().getName());
        PlayerRole role = roster.getRole(rsn);
        if (role == PlayerRole.GUARD) return "GUARD";
        if (role == PlayerRole.CONTESTANT) return "CONTESTANT";
        return null;
    }

    private static boolean isVisibleToRole(TileMarkerReducer.TileMarkerEntry entry, String localRole)
    {
        if (entry.visibleTo == null || entry.visibleTo.isEmpty()) return false;
        if (localRole == null) return false;
        return entry.visibleTo.contains(localRole);
    }

    // -------------------------------------------------------------------------
    // Color helpers
    // -------------------------------------------------------------------------

    private Color resolveColor(TileMarkerReducer.TileMarkerEntry entry)
    {
        return classDefaultColor(entry.tileClass);
    }

    private Color classDefaultColor(String tileClass)
    {
        if (tileClass == null) return COLOR_STANDARD;
        switch (tileClass.toUpperCase())
        {
            case "LANDMINE":            return COLOR_LANDMINE;
            case "LANDMINE_DETONATED":  return COLOR_LANDMINE_DETONATED;
            case "STOPLIGHT":
                return "RED".equals(tileMarkers.getStoplightState())
                        ? COLOR_STOPLIGHT_RED : COLOR_STOPLIGHT_GREEN;
            default:          return COLOR_STANDARD;
        }
    }

}

