    private static void styleScrollPane(JScrollPane pane)
    {
        final JScrollBar vsb = pane.getVerticalScrollBar();
        vsb.setPreferredSize(new java.awt.Dimension(6, Integer.MAX_VALUE));
        vsb.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        vsb.setUI(new javax.swing.plaf.basic.BasicScrollBarUI()
        {
            @Override
            protected void configureScrollBarColors()
            {
                thumbColor = ColorScheme.MEDIUM_GRAY_COLOR;
                trackColor = ColorScheme.DARKER_GRAY_COLOR;
            }

            @Override
            protected JButton createDecreaseButton(int orientation)
            {
                return zeroButton();
            }

            @Override
            protected JButton createIncreaseButton(int orientation)
            {
                return zeroButton();
            }

            private JButton zeroButton()
            {
                final JButton btn = new JButton();
                btn.setPreferredSize(new java.awt.Dimension(0, 0));
                btn.setMinimumSize(new java.awt.Dimension(0, 0));
                btn.setMaximumSize(new java.awt.Dimension(0, 0));
                return btn;
            }
        });
    }

    private static void styleBtn(JButton btn)
    {
        btn.setBackground(ColorScheme.DARK_GRAY_COLOR);
        btn.setForeground(Color.WHITE);
        btn.setOpaque(true);
        btn.setFocusPainted(false);
        btn.setBorder(
                BorderFactory.createCompoundBorder(
                        BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR, 1),
                        BorderFactory.createEmptyBorder(5, 10, 5, 10)
                )
        );
        btn.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseEntered(MouseEvent e)
            {
                btn.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
            }

            @Override
            public void mouseExited(MouseEvent e)
            {
                btn.setBackground(ColorScheme.DARK_GRAY_COLOR);
            }
        });
    }

    private static void styleToggleBtn(JToggleButton btn, Color inactiveFg, Color selectedBg, Color selectedFg)
    {
        btn.setUI(new javax.swing.plaf.basic.BasicToggleButtonUI());
        btn.setForeground(inactiveFg);
        btn.setOpaque(true);
        btn.setFocusPainted(false);
        btn.setBorder(
                BorderFactory.createCompoundBorder(
                        BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR, 1),
                        BorderFactory.createEmptyBorder(5, 10, 5, 10)
                )
        );
        btn.addChangeListener(e ->
        {
            btn.setBackground(btn.isSelected() ? selectedBg : ColorScheme.DARK_GRAY_COLOR);
            btn.setForeground(btn.isSelected() ? selectedFg : inactiveFg);
        });
        btn.addMouseListener(new MouseAdapter()
        {
            @Override
            public void mouseEntered(MouseEvent e)
            {
                if (!btn.isSelected()) btn.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
            }

            @Override
            public void mouseExited(MouseEvent e)
            {
                if (!btn.isSelected()) btn.setBackground(ColorScheme.DARK_GRAY_COLOR);
            }
        });
        btn.setBackground(ColorScheme.DARK_GRAY_COLOR);
    }

