    @Subscribe
    public void onMenuEntryAdded(MenuEntryAdded e)
    {
        // Inject "Enlist" on player right-click, only when the local player is an active commander.
        // "Follow" is a standard game option that always appears for other players, used as a
        // single-fire trigger so we add Enlist exactly once per context menu.
        if ("Follow".equals(e.getOption())
                && e.getMenuEntry().getActor() instanceof Player
                && gameService != null
                && gameService.isLocalCommander()
                && gameService.getActiveGameId() != null
                && !gameService.getActiveGameId().isBlank())
        {
            MenuEntry enlistEntry = client.createMenuEntry(-1)
                    .setOption("Enlist")
                    .setTarget(e.getTarget())
                    .setType(MenuAction.RUNELITE_PLAYER)
                    .setIdentifier(e.getIdentifier());

            final String contestantHex = String.format("%06X", RoleOverlay.CONTESTANT_ALIVE_COLOR.getRGB() & 0xFFFFFF);
            final String guardHex      = String.format("%06X", RoleOverlay.GUARD_COLOR.getRGB() & 0xFFFFFF);

            Menu subMenu = enlistEntry.createSubMenu();
            subMenu.createMenuEntry(-1)
                    .setOption("Remove")
                    .setTarget("")
                    .setType(MenuAction.RUNELITE_PLAYER)
                    .setIdentifier(e.getIdentifier())
                    .onClick(me -> handleEnlistSubOption(me, null));
            subMenu.createMenuEntry(-1)
                    .setOption("<col=" + guardHex + ">Guard</col>")
                    .setTarget("")
                    .setType(MenuAction.RUNELITE_PLAYER)
                    .setIdentifier(e.getIdentifier())
                    .onClick(me -> handleEnlistSubOption(me, PlayerRole.GUARD));
            subMenu.createMenuEntry(-1)
                    .setOption("<col=" + contestantHex + ">Contestant</col>")
                    .setTarget("")
                    .setType(MenuAction.RUNELITE_PLAYER)
                    .setIdentifier(e.getIdentifier())
                    .onClick(me -> handleEnlistSubOption(me, PlayerRole.CONTESTANT));
        }

        // Tile marking: inject when Commander shift+right-clicks the ground
        if ("Walk here".equals(e.getOption())
                && gameService != null
                && gameService.isLocalCommander()
                && client.isKeyPressed(KeyCode.KC_SHIFT))
        {
            Tile selectedTile = client.getSelectedSceneTile();
            if (selectedTile != null)
            {
                final WorldPoint wp = selectedTile.getWorldLocation();

                boolean alreadyMarked = tileMarkerReducer.getMarker(wp) != null;

                // Deprioritize all existing entries so our option wins the left-click slot
                for (MenuEntry entry : client.getMenuEntries())
                {
                    entry.setDeprioritized(true);
                }

                if (alreadyMarked)
                {
                    // Quick configure tile below, Reset tile on top
                    if (lastTileConfig != null)
                    {
                        client.createMenuEntry(-1)
                                .setOption("Quick configure tile")
                                .setTarget("")
                                .setType(MenuAction.RUNELITE)
                                .setDeprioritized(false)
                                .onClick(me -> handleQuickMarkTile(wp));
                    }
                    client.createMenuEntry(-1)
                            .setOption("Reset tile")
                            .setTarget("")
                            .setType(MenuAction.RUNELITE)
                            .setDeprioritized(false)
                            .onClick(me -> handleUnmarkTile(wp));
                }
                else
                {
                    // Configure tile below, Quick configure tile on top (if available)
                    client.createMenuEntry(-1)
                            .setOption("Configure tile")
                            .setTarget("")
                            .setType(MenuAction.RUNELITE)
                            .setDeprioritized(false)
                            .onClick(me -> handleMarkTile(wp));
                    if (lastTileConfig != null)
                    {
                        client.createMenuEntry(-1)
                                .setOption("Quick configure tile")
                                .setTarget("")
                                .setType(MenuAction.RUNELITE)
                                .setDeprioritized(false)
                                .onClick(me -> handleQuickMarkTile(wp));
                    }
                }
            }
        }
    }

    /**
     * Vanilla item special-attack options (e.g. "Enamour" on the Love Crossbow) are not entries
     * we create, so we cannot attach an onClick consumer to them. Listen passively here so the
     * special attack still fires normally and we layer the elimination on top.
     */
    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        final String opt = event.getMenuOption();
        if (opt != null && ELIMINATE_OPTIONS.contains(opt))
        {
            handleEliminate(event);
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (gameService == null) return;
        final boolean isCommander = gameService.isLocalCommander();
        final boolean isGuard = isLocalGuard();
        if (!isCommander && !isGuard) return;

        String gameId = gameService.getActiveGameId();
        if (gameId == null || gameId.isBlank()) return;

        // Stoplight: eliminate players on STOPLIGHT tiles every tick while state is RED
        if ("RED".equals(tileMarkerReducer.getStoplightState()))
        {
            eliminatePlayersOnStoplightTiles(isCommander);
        }

        if (tileMarkerReducer.snapshotLandmines().isEmpty()) return;

        for (Player p : client.getPlayers())
        {
            if (p == null || p.getName() == null) continue;
            String rsn = Text.toJagexName(p.getName());
            if (rsn == null || rsn.isBlank()) continue;

            if (rosterReducer.getRole(rsn) != PlayerRole.CONTESTANT) continue;
            if (rosterReducer.getStatus(rsn) == PlayerStatus.ELIMINATED) continue;
            if (pendingEliminations.contains(rsn.toLowerCase(Locale.ROOT))) continue;

            TileMarkerReducer.TileMarkerEntry landmine =
                    tileMarkerReducer.getMarker(p.getWorldLocation());
            if (landmine == null || !"LANDMINE".equalsIgnoreCase(landmine.tileClass)) continue;

            pendingEliminations.add(rsn.toLowerCase(Locale.ROOT));
            final String victim = rsn;
            final TileMarkerReducer.TileMarkerEntry triggeredTile = landmine;
            executor.execute(() ->
            {
                try
                {
                    if (isCommander) gameService.eliminate(victim);
                    else             gameService.eliminateAsGuard(victim);
                }
                catch (Exception ex)
                {
                    log.warn("Landmine eliminate failed for {}", victim, ex);
                    pendingEliminations.remove(victim.toLowerCase(Locale.ROOT));
                }
                try
                {
                    if (isCommander)
                    {
                        Set<String> everyone = new HashSet<>(Arrays.asList(
                                "COMMANDER", "GUARD", "CONTESTANT"));
                        gameService.markTile(triggeredTile.point, triggeredTile.label,
                                "LANDMINE_DETONATED", everyone);
                    }
                    else
                    {
                        gameService.detonateAsGuard(triggeredTile.point);
                    }
                }
                catch (Exception ex)
                {
                    log.warn("Landmine reveal failed", ex);
                }
            });
        }
    }

    /** Must be called on the client thread. Eliminates all contestants currently on STOPLIGHT tiles. */
    private void eliminatePlayersOnStoplightTiles(boolean isCommander)
    {
        List<TileMarkerReducer.TileMarkerEntry> stoplights =
                tileMarkerReducer.snapshotStoplights();
        if (stoplights.isEmpty()) return;

        Set<WorldPoint> stoplightPoints = new HashSet<>();
        for (TileMarkerReducer.TileMarkerEntry sl : stoplights)
        {
            stoplightPoints.add(sl.point);
        }

        for (Player p : client.getPlayers())
        {
            if (p == null || p.getName() == null) continue;
            String rsn = Text.toJagexName(p.getName());
            if (rsn == null || rsn.isBlank()) continue;
            if (rosterReducer.getRole(rsn) != PlayerRole.CONTESTANT) continue;
            if (rosterReducer.getStatus(rsn) == PlayerStatus.ELIMINATED) continue;
            if (pendingEliminations.contains(rsn.toLowerCase(Locale.ROOT))) continue;

            if (stoplightPoints.contains(p.getWorldLocation()))
            {
                pendingEliminations.add(rsn.toLowerCase(Locale.ROOT));
                final String victim = rsn;
                executor.execute(() ->
                {
                    try
                    {
                        if (isCommander) gameService.eliminate(victim);
                        else             gameService.eliminateAsGuard(victim);
                    }
                    catch (Exception ex)
                    {
                        log.warn("Stoplight eliminate failed for {}", victim, ex);
                        pendingEliminations.remove(victim.toLowerCase(Locale.ROOT));
                    }
                });
            }
        }
    }

    /** Handles a child option from the "Enlist >" sub-menu. role=null means Remove. */
    private void handleEnlistSubOption(MenuEntry menuEntry, PlayerRole role)
    {
        // Prefer player lookup via identifier (target is empty on sub-menu children)
        final String target;
        Player clickedPlayer = menuEntry.getPlayer();
        if (clickedPlayer != null && clickedPlayer.getName() != null)
        {
            target = Text.toJagexName(clickedPlayer.getName());
        }
        else
        {
            target = resolveMenuTarget(menuEntry.getTarget());
        }
        if (target == null || target.isBlank())
        {
            return;
        }

        if (gameService.getActiveGameId() == null || gameService.getActiveGameId().isBlank())
        {
            return;
        }

        if (role == null)
        {
            remove(target);
            return;
        }

        if (role == PlayerRole.GUARD && !rosterReducer.hasJoined(target))
        {
            SwingUtilities.invokeLater(() ->
            {
                int confirm = JOptionPane.showConfirmDialog(
                        null,
                        target + " has not joined this game via the Skwid Games plugin.\n"
                        + "Guards need the plugin running to monitor tile-based triggers.\n\n"
                        + "Enlist them as a Guard anyway?",
                        "Skwid Games — Guard Warning",
                        JOptionPane.YES_NO_OPTION,
                        JOptionPane.WARNING_MESSAGE
                );
                if (confirm == JOptionPane.YES_OPTION)
                {
                    enlist(target, PlayerRole.GUARD);
                }
            });
            return;
        }

        enlist(target, role);
    }

    private void handleEliminate(MenuOptionClicked event)
    {
        String target = resolveMenuTarget(event.getMenuTarget());
        if (target == null || target.isBlank())
        {
            return;
        }

        String active = gameService.getActiveGameId();
        if (active == null || active.isBlank())
        {
            return;
        }

        // Only contestants can be eliminated
        PlayerRole role = rosterReducer.getRole(target);
        if (role != PlayerRole.CONTESTANT)
        {
            return;
        }

        // Optional: ignore if already eliminated
        if (rosterReducer.getStatus(target) == PlayerStatus.ELIMINATED)
        {
            return;
        }

        // Determine if the local player has permission to eliminate
        final boolean isCommander = gameService.isLocalCommander();
        final String localName = client.getLocalPlayer() != null ? Text.toJagexName(client.getLocalPlayer().getName()) : null;
        final boolean isGuard = localName != null && rosterReducer.getRole(localName) == PlayerRole.GUARD;

        if (!isCommander && !isGuard)
        {
            return;
        }

        executor.execute(() ->
        {
            try
            {
                if (isCommander)
                {
                    gameService.eliminate(target);
                }
                else
                {
                    gameService.eliminateAsGuard(target);
                }
                chat("Eliminated " + target + ".");
            }
            catch (Exception ex)
            {
                chat("Failed to eliminate " + target + ": " + ex.getMessage());
                log.warn("Failed to eliminate {}", target, ex);
            }
        });
    }

    private void enlist(String target, PlayerRole playerRole)
    {
        executor.execute(() ->
        {
            try
            {
                gameService.enlist(target, playerRole);
                chat("Enlisted " + target + " as " + playerRole.name() + ".");
            }
            catch (Exception e)
            {
                chat("Failed to enlist: " + e.getMessage());
            }
        });
    }

    private void remove(String target)
    {
        executor.execute(() ->
        {
            try
            {
                gameService.removePlayer(target);
                chat("Removed " + target + " from the game.");
            }
            catch (Exception e)
            {
                chat("Failed to remove: " + e.getMessage());
            }
        });
    }

    private void handleMarkTile(WorldPoint wp)
    {
        SwingUtilities.invokeLater(() ->
        {
            // --- Label ---
            JTextField labelField = new JTextField(16);

            // --- Tile class radio buttons ---
            String[] classes = {"STANDARD", "LANDMINE", "STOPLIGHT"};
            ButtonGroup classGroup = new ButtonGroup();
            JRadioButton[] classButtons = new JRadioButton[classes.length];
            JPanel classPanel = new JPanel();
            for (int i = 0; i < classes.length; i++)
            {
                classButtons[i] = new JRadioButton(classes[i]);
                classGroup.add(classButtons[i]);
                classPanel.add(classButtons[i]);
            }
            classButtons[0].setSelected(true); // STANDARD default

            // --- Visibility checkboxes ---
            JCheckBox cbCommander  = new JCheckBox("Commander",  true);
            JCheckBox cbGuard      = new JCheckBox("Guard",      true);
            JCheckBox cbContestant = new JCheckBox("Contestant", true);
            JPanel visPanel = new JPanel();
            visPanel.add(cbCommander);
            visPanel.add(cbGuard);
            visPanel.add(cbContestant);

            // --- Assemble panel ---
            JPanel panel = new JPanel(new GridLayout(0, 1, 4, 4));
            panel.add(new JLabel("Label (optional):"));
            panel.add(labelField);
            panel.add(new JLabel("Class:"));
            panel.add(classPanel);
            panel.add(new JLabel("Visible to:"));
            panel.add(visPanel);

            int result = JOptionPane.showConfirmDialog(
                    null, panel, "Configure Tile",
                    JOptionPane.OK_CANCEL_OPTION, JOptionPane.PLAIN_MESSAGE);

            if (result != JOptionPane.OK_OPTION) return;

            // Collect values
            String rawLabel = labelField.getText().trim();
            final String finalLabel = rawLabel.isEmpty() ? null : rawLabel;

            String selectedClass = "STANDARD";
            for (int i = 0; i < classes.length; i++)
            {
                if (classButtons[i].isSelected())
                {
                    selectedClass = classes[i];
                    break;
                }
            }
            final String finalClass = selectedClass;

            Set<String> visibleTo = new HashSet<>();
            if (cbCommander.isSelected())  visibleTo.add("COMMANDER");
            if (cbGuard.isSelected())      visibleTo.add("GUARD");
            if (cbContestant.isSelected()) visibleTo.add("CONTESTANT");
            final Set<String> finalVisibleTo = visibleTo;

            // Save as the last-used config for quick-mark
            lastTileConfig = new TileConfig(finalLabel, finalClass, new HashSet<>(finalVisibleTo));

            executor.execute(() ->
            {
                try
                {
                    gameService.markTile(wp, finalLabel, finalClass, finalVisibleTo);
                }
                catch (Exception ex)
                {
                    chat("Failed to configure tile: " + ex.getMessage());
                    log.warn("Failed to configure tile", ex);
                }
            });
        });
    }

    private void handleQuickMarkTile(WorldPoint wp)
    {
        TileConfig cfg = lastTileConfig;
        if (cfg == null) return;
        executor.execute(() ->
        {
            try
            {
                gameService.markTile(wp, cfg.label, cfg.tileClass, cfg.visibleTo);
            }
            catch (Exception ex)
            {
                chat("Failed to quick configure tile: " + ex.getMessage());
                log.warn("Failed to quick configure tile", ex);
            }
        });
    }

    private void handleUnmarkTile(WorldPoint wp)
    {
        executor.execute(() ->
        {
            try
            {
                gameService.unmarkTile(wp);
            }
            catch (Exception ex)
            {
                chat("Failed to unmark tile: " + ex.getMessage());
                log.warn("Failed to unmark tile", ex);
            }
        });
    }

    private void chat(String msg)
    {
        clientThread.invoke(() ->
                client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", msg, null));
    }

    private String resolveMenuTarget(String menuTarget)
    {
        return canonicalizeMenuTarget(menuTarget);
    }

    private static String canonicalizeMenuTarget(String menuTarget)
    {
        if (menuTarget == null) return null;

        String s = Text.removeTags(menuTarget);

        // handle both "(level 126)" and "(level-126)" and extra spaces
        s = s.replaceFirst("\\s*\\(level\\s*-?\\s*\\d+\\)\\s*$", "");

        return Text.toJagexName(s);
    }
}

package gay.runescape;

import com.google.gson.JsonElement;
import net.runelite.api.coords.WorldPoint;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;

public class TileMarkerReducer
{
    public static final class TileMarkerEntry
    {
        public final WorldPoint point;
        public final String label;
        public final String color;
        public final String markedBy;
        /** One of: "STANDARD", "LANDMINE", "STOPLIGHT". Null treated as STANDARD. */
        public final String tileClass;
        /** Roles that can see this tile. Empty set = visible to no one. */
        public final Set<String> visibleTo;

        public TileMarkerEntry(WorldPoint point, String label, String color,
                               String markedBy, String tileClass, Set<String> visibleTo)
        {
            this.point     = point;
            this.label     = label;
            this.color     = color;
            this.markedBy  = markedBy;
            this.tileClass = tileClass;
            this.visibleTo = (visibleTo != null) ? visibleTo : Collections.emptySet();
        }
    }

    private final ConcurrentHashMap<String, TileMarkerEntry> markers = new ConcurrentHashMap<>();
    private volatile String stoplightState = "GREEN";

    public String getStoplightState()
    {
        return stoplightState;
    }

    public void setStoplightState(String state)
    {
        if ("RED".equalsIgnoreCase(state) || "GREEN".equalsIgnoreCase(state))
        {
            stoplightState = state.toUpperCase(Locale.ROOT);
        }
    }

    public void apply(RelayClient.EventOut e)
    {
        if (e == null || e.type == null) return;

        final String type = e.type.toUpperCase(Locale.ROOT);

        if ("TILE_MARKED".equals(type))
        {
            Integer x     = safeInt(e.payload, "x");
            Integer y     = safeInt(e.payload, "y");
            Integer plane = safeInt(e.payload, "plane");
            if (x == null || y == null || plane == null) return;

            String label     = safeStr(e.payload, "label");
            String color     = safeStr(e.payload, "color");
            String markedBy  = safeStr(e.payload, "markedBy");
            String tileClass = safeStr(e.payload, "tileClass");

            Set<String> visibleTo = Collections.emptySet();
            if (e.payload != null && e.payload.has("visibleTo")
                    && e.payload.get("visibleTo").isJsonArray())
            {
                Set<String> roles = new HashSet<>();
                for (JsonElement el : e.payload.getAsJsonArray("visibleTo"))
                {
                    if (!el.isJsonNull())
                    {
                        roles.add(el.getAsString().toUpperCase(Locale.ROOT));
                    }
                }
                visibleTo = Collections.unmodifiableSet(roles);
            }

            WorldPoint wp = new WorldPoint(x, y, plane);
            markers.put(key(x, y, plane),
                    new TileMarkerEntry(wp, label, color, markedBy, tileClass, visibleTo));
            return;
        }

        if ("STOPLIGHT_STATE".equals(type))
        {
            String state = safeStr(e.payload, "state");
            if ("RED".equalsIgnoreCase(state) || "GREEN".equalsIgnoreCase(state))
            {
                stoplightState = state.toUpperCase(Locale.ROOT);
            }
            return;
        }

        if ("TILE_UNMARKED".equals(type))
        {
            Integer x     = safeInt(e.payload, "x");
            Integer y     = safeInt(e.payload, "y");
            Integer plane = safeInt(e.payload, "plane");
            if (x == null || y == null || plane == null) return;

            markers.remove(key(x, y, plane));
        }
    }

    public void loadAll(List<TileMarkerEntry> entries)
    {
        if (entries == null) return;
        for (TileMarkerEntry entry : entries)
        {
            if (entry == null || entry.point == null) continue;
            markers.put(key(entry.point.getX(), entry.point.getY(), entry.point.getPlane()), entry);
        }
    }

    /** Returns only tiles whose tileClass is "STOPLIGHT". */
    public List<TileMarkerEntry> snapshotStoplights()
    {
        List<TileMarkerEntry> out = new ArrayList<>();
        for (TileMarkerEntry entry : markers.values())
        {
            if ("STOPLIGHT".equalsIgnoreCase(entry.tileClass))
            {
                out.add(entry);
            }
        }
        return out;
    }

    public void reset()
    {
        markers.clear();
        stoplightState = "GREEN";
    }

    public List<TileMarkerEntry> snapshot()
    {
        return Collections.unmodifiableList(new ArrayList<>(markers.values()));
    }

    /** Returns only tiles whose tileClass is "LANDMINE". */
    public List<TileMarkerEntry> snapshotLandmines()
    {
        List<TileMarkerEntry> out = new ArrayList<>();
        for (TileMarkerEntry entry : markers.values())
        {
            if ("LANDMINE".equalsIgnoreCase(entry.tileClass))
            {
                out.add(entry);
            }
        }
        return out;
    }

    public TileMarkerEntry getMarker(WorldPoint wp)
    {
        if (wp == null) return null;
        return markers.get(key(wp.getX(), wp.getY(), wp.getPlane()));
    }

    static String key(int x, int y, int plane)
    {
        return x + ":" + y + ":" + plane;
    }

    private static String safeStr(com.google.gson.JsonObject o, String k)
    {
        return (o != null && o.has(k) && !o.get(k).isJsonNull())
                ? o.get(k).getAsString()
                : null;
    }

    private static Integer safeInt(com.google.gson.JsonObject o, String k)
    {
        try
        {
            return (o != null && o.has(k) && !o.get(k).isJsonNull())
                    ? o.get(k).getAsInt()
                    : null;
        }
        catch (Exception ignored)
        {
            return null;
        }
    }
}

